/**
 * NPC 地图显隐与碰撞：appear 管 sprite；可选 sequential 仅限制碰撞体。
 */
import { BoxCollider2D, Node } from 'cc';
import {
  isBattleEnemyNpcUid,
  npcAppearRequirementsMet,
  pickInteractEvent,
  type StoryEventLike,
  type StoryEventPageContext,
  type StoryNpcAppear,
} from './story-event-page-resolver';

export type StoryNpcDisplayRow = {
  npcUid: string;
  node: Node;
  events: StoryEventLike[];
  appear?: StoryNpcAppear;
  initialHidden?: boolean;
};

export type SyncStoryNpcDisplayOptions = {
  rows: StoryNpcDisplayRow[];
  pageCtx: StoryEventPageContext;
  sequentialGate: boolean;
  activationNpcUid: string | null;
  requirementsMet: (reqs: unknown[] | undefined) => boolean;
  resolveFocusUid: () => string | null;
  isNpcHidden: (npcUid: string) => boolean;
};


export function pickEnemyInteractEvent(
  npcUid: string,
  events: StoryEventLike[] | null | undefined,
  pageCtx: StoryEventPageContext,
): StoryEventLike | null {
  const list = events ?? [];
  const active = pickInteractEvent(npcUid, list, pageCtx);
  if (active) return active;
  const sorted = [...list].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
  for (const ev of sorted) {
    if (pageCtx.isStepComplete(npcUid, ev)) continue;
    if (pageCtx.requirementsMet(ev.server?.requirements as unknown[] | undefined)) return ev;
  }
  return null;
}

export function isNpcHiddenUntilReveal(
  row: Pick<StoryNpcDisplayRow, 'appear' | 'initialHidden'> | undefined,
  revealed: boolean,
  requirementsMet: (reqs: unknown[] | undefined) => boolean,
): boolean {
  if (!row) return false;
  if (revealed) return false;
  if (npcAppearRequirementsMet(row.appear, row.initialHidden, requirementsMet)) return false;
  if (!row.appear && !row.initialHidden) return false;
  return true;
}

export function syncStoryNpcDisplay(opts: SyncStoryNpcDisplayOptions): void {
  const { rows, pageCtx, sequentialGate, activationNpcUid, resolveFocusUid, isNpcHidden } = opts;
  const focusUid = sequentialGate ? resolveFocusUid() : null;

  for (const row of rows) {
    if (!row.node?.isValid) continue;
    row.node.active = !isNpcHidden(row.npcUid);
  }

  for (const row of rows) {
    if (!row.node?.isValid) continue;
    const bc = row.node.getComponent(BoxCollider2D);
    if (!bc) continue;

    if (!row.node.active) {
      bc.enabled = false;
      continue;
    }

    if (isBattleEnemyNpcUid(row.npcUid)) {
      bc.enabled = true;
      continue;
    }

    if (!sequentialGate) {
      const page = pickInteractEvent(row.npcUid, row.events ?? [], pageCtx);
      bc.enabled = page !== null || activationNpcUid === row.npcUid;
      continue;
    }

    if (activationNpcUid === row.npcUid) {
      bc.enabled = true;
      continue;
    }

    if (isBattleEnemyNpcUid(row.npcUid)) {
      bc.enabled = pickInteractEvent(row.npcUid, row.events, pageCtx) !== null;
      continue;
    }

    bc.enabled = focusUid !== null && row.npcUid === focusUid;
  }
}

export function canPlayerInteractWithNpc(
  npcUid: string,
  rows: StoryNpcDisplayRow[],
  pageCtx: StoryEventPageContext,
  sequentialGate: boolean,
  activationNpcUid: string | null,
  resolveFocusUid: () => string | null,
): boolean {
  const evs = (row: StoryNpcDisplayRow | undefined) => row?.events ?? [];

  if (!sequentialGate) {
    const row = rows.find((r) => r.npcUid === npcUid);
    if (!row?.node?.active) return false;
    if (isBattleEnemyNpcUid(npcUid)) {
      if (activationNpcUid === npcUid) return true;
      return evs(row).some((ev) => !pageCtx.isStepComplete(npcUid, ev));
    }
    return pickInteractEvent(npcUid, evs(row), pageCtx) !== null || activationNpcUid === npcUid;
  }
  if (activationNpcUid === npcUid) return true;
  if (isBattleEnemyNpcUid(npcUid)) {
    const row = rows.find((r) => r.npcUid === npcUid);
    if (!row?.node?.active) return false;
    return evs(row).some((ev) => !pageCtx.isStepComplete(npcUid, ev));
  }
  return resolveFocusUid() === npcUid;
}
